import { NavLink, Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';
import { useCart } from '../context/CartContext';
import { useOrders } from '../context/OrderContext';

const linkClass = ({ isActive }) =>
  'text-sm transition flex items-center gap-1 ' +
  (isActive ? 'font-medium text-amber-600' : 'text-slate-500 hover:text-amber-600');

function Navbar() {
  const { isLoggedIn, isAdmin, member, logout } = useAuth();
  const { totalCount } = useCart();
  const { pendingCount } = useOrders();
  const navigate = useNavigate();

  function handleLogout() {
    logout();
    navigate('/');
  }

  return (
    <header className="border-b border-amber-100 bg-white sticky top-0 z-30 shadow-xs">
      <nav className="mx-auto flex max-w-5xl flex-wrap items-center gap-x-6 gap-y-2 px-4 py-3.5 md:px-6">
        <Link to="/" className="text-lg font-bold tracking-tight text-amber-700">
          📚 NangSuKub
        </Link>
        <div className="flex flex-wrap items-center gap-4 md:gap-5">
          <NavLink to="/" end className={linkClass}>หน้าแรก</NavLink>
          <NavLink to="/books" className={linkClass}>หนังสือ</NavLink>
          {isLoggedIn && (
            <>
              <NavLink to="/cart" className={linkClass}>
                <span>🛒 ตะกร้า</span>
                {totalCount > 0 && (
                  <span className="inline-flex h-4 min-w-[16px] items-center justify-center rounded-full bg-amber-500 px-1 text-[10px] font-bold text-white">
                    {totalCount}
                  </span>
                )}
              </NavLink>
              <NavLink to="/me/library" className={linkClass}>
                <span>📚 ชั้นหนังสือ</span>
              </NavLink>
              <NavLink to="/me/orders" className={linkClass}>
                <span>📋 คำสั่งซื้อ</span>
              </NavLink>
              <NavLink to="/me/wishlist" className={linkClass}>
                <span>❤️ อยากอ่าน</span>
              </NavLink>
            </>
          )}
          <NavLink to="/about" className={linkClass}>เกี่ยวกับ</NavLink>
          {isAdmin && (
            <NavLink to="/admin" className={linkClass}>
              <span>หลังบ้าน</span>
              {pendingCount > 0 && (
                <span className="inline-flex h-4 min-w-[16px] items-center justify-center rounded-full bg-red-500 px-1 text-[10px] font-bold text-white animate-pulse">
                  {pendingCount}
                </span>
              )}
            </NavLink>
          )}
        </div>
        <div className="ml-auto flex items-center gap-3 text-sm">
          {isLoggedIn ? (
            <>
              <span className="text-slate-600 text-xs md:text-sm">
                👤 {member?.displayName}
                {isAdmin && <span className="ml-1 text-[10px] bg-amber-100 text-amber-800 px-1.5 py-0.5 rounded font-bold">Admin</span>}
              </span>
              <button onClick={handleLogout} className="text-slate-400 hover:text-amber-600 text-xs">
                ออกจากระบบ
              </button>
            </>
          ) : (
            <Link to="/login" className="rounded-lg border border-amber-200 bg-white px-3 py-1.5 text-xs md:text-sm font-medium text-amber-700 hover:bg-amber-50 shadow-xs">
              เข้าสู่ระบบ
            </Link>
          )}
        </div>
      </nav>
    </header>
  );
}

export default Navbar;
